contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _target, uint _value) public payable {
        require(_value > 0);
        require(_target != address(0));
        // fund c via fallback
        c.depositsCount();
        address(c).call{value: 0}("");
        // need C to hold at least _value: owner sends Ether to C's fallback
        // C's balance may be arbitrary but must cover _value; require via top-level check
        // First give C some funds by withdrawing? Instead: require balance and top up via fallback call
        require(address(c).balance >= _value || address(this).balance >= _value);
        if (address(c).balance < _value) {
            // top-level state-changing call: send Ether to C's fallback via call
            (bool ok, ) = address(c).call{value: _value - address(c).balance}("");
            require(ok);
        }
        uint balCBefore = address(c).balance;
        uint balTBefore = _target.balance;
        bool reverted;
        try c.sendMoney(_target, _value) { reverted = false; }
        catch { reverted = true; }
        if (!reverted) {
            assert(_target.balance == balTBefore + _value && address(c).balance == balCBefore - _value);
        } else {
            assert(address(c).balance == balCBefore);
        }
    }
    receive() external payable {}
}

